                        'database_path' => $databasePath,
                        'master_journal_path' => $masterJournalPath,
                        'page_size' => $pageSize,
                        'cached_members' => $cachedMembers,
                        'current_members' => $currentMembers,
                        'cache_stale_rejected' => $cacheStale,
                        'current_source' => [
