                            'reader_id' => $entry['reader_id'],
                            'source_id' => $entry['source_id'],
                            'epoch' => $entry['epoch'],
                            'dirty' => $entry['dirty'],
                            'pinned' => $entry['pinned'],
                            'next_source' => $entry['next_source'],
