                        'database_path' => $databasePath,
                        'master_journal_path' => $masterJournalPath,
                        'page_size' => $pageSize,
                        'current_members' => $currentMembers,
                        'current_master_journal_digest' => $currentDigest,
                        'current_source' => [
                            'id' => $currentSourceId,
                            'epoch' => $currentEpoch,
                            'change_counter' => $currentChangeCounter,
