                                'format_signature_current' => $format['signature'],
                                'dirty' => $entry['dirty'],
                                'pinned' => $entry['pinned'],
                            ];
                            $operations[] = [
                                'op' => 'invalidate_reader_cache_after_format_ticket_recheck_next180',
                                'page_number' => $pageNumber,
                                'reader_id' => $entry['reader_id'],
                                'reason' => $reason,
                            ];
                        } elseif ($entry['image'] !== $currentImage) {
