                    $unpacked = unpack('n', substr($bytes, $offset, 2));

                    return $unpacked[1];
                }

                private static function u32(string $bytes, int $offset): int
                {
                    /** @var array{1:int} $unpacked */
                    $unpacked = unpack('N', substr($bytes, $offset, 4));

                    return $unpacked[1];
