                {
                    ksort($database, SORT_NUMERIC);
                    $bytes = '';
                    foreach ($database as $entry) {
                        $bytes .= str_pad(substr($entry['image'], 0, $pageSize), $pageSize, "\0", STR_PAD_RIGHT);
                    }

                    return $bytes;
                }

                private static function label(string $image): string
                {
                    return rtrim(strtok($image, "\0") ?: $image, ". \0");
                }
        })->plan($databasePath, $masterJournalPath, $currentMasterJournalBytes, $databaseBytes, $pageSize, $recoveredPages, $readerCache, $nextReads, $currentSourceId, $currentEpoch);
