    /**
     * @return list<string>
     */
    private static function canonicalMemberPathReaderCacheMembers(string $bytes): array
    {
        $members = [];
        foreach (preg_split('/\r?\n/', $bytes) ?: [] as $line) {
            $line = trim($line);
            if ($line !== '') {
                $members[] = $line;
            }
        }

        return $members;
    }

    /**
     * @param list<string> $members
     * @param array<string,string> $canonicalPathMap
     * @return list<string>
